package com.justjava.humanresource.employeeexit.service; import com.justjava.humanresource.employeeexit.entity.ExitAssetReturn; import com.justjava.humanresource.employeeexit.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class ExitAssetSnapshotService {private final EmployeeExitService exits;private final EmployeeAssignedAssetRepository assigned;private final ExitAssetReturnRepository snapshots;private final EmployeeExitActivityService activity;
 @Transactional public List<ExitAssetReturn> snapshotAssignedAssets(Long exitId){var x=exits.require(exitId);int before=snapshots.findByExitCaseIdOrderByAssetName(exitId).size();for(var source:assigned.findByEmployeeIdAndActiveTrue(x.getEmployeeId())){if(snapshots.existsByExitCaseIdAndExternalAssetId(exitId,source.getExternalAssetId()))continue;ExitAssetReturn a=new ExitAssetReturn();a.setExitCaseId(exitId);a.setExternalAssetId(source.getExternalAssetId());a.setExternalAssetCode(source.getExternalAssetCode());a.setAssetName(source.getAssetName());a.setCategory(source.getCategory());a.setAssessedValue(source.getAssessedValue());a.setExpectedReturnDate(x.getEffectiveExitDate());snapshots.save(a);}var result=snapshots.findByExitCaseIdOrderByAssetName(exitId);activity.record(exitId,"ASSETS_SYNCED",(result.size()-before)+" assigned asset(s) added to exit snapshot",null,null);return result;}}
